/**
 * AI chat history route — GET /api/ai-chat/history?conversation=<token>
 *
 * The messages of one of the caller's own conversations, so the chat can pick a
 * conversation back up after a reload or from its recent list. The token is the
 * signed one /api/ai-chat issued; a token issued to someone else is a 404.
 *
 * Generated by @buildpad/cli
 */
import { NextRequest, NextResponse } from 'next/server';
import { toUIMessages } from '@/components/ui/ai-chat/history';
import { authHeaders, chatOwner, chocolateFactorySettings, hasTokenSecret, verifyConversation } from '@/lib/ai-chat/server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  const settings = chocolateFactorySettings();
  if (!settings || !hasTokenSecret()) return NextResponse.json({ error: 'The assistant is not configured.' }, { status: 503 });

  const { owner, isNew } = chatOwner(request);
  const conversationId = isNew ? null : verifyConversation(owner, request.nextUrl.searchParams.get('conversation'));
  if (!conversationId) return NextResponse.json({ error: 'Conversation not found.' }, { status: 404 });

  try {
    const res = await fetch(
      `${settings.baseUrl}/api/agents/${encodeURIComponent(settings.agentId)}/conversations/${encodeURIComponent(conversationId)}`,
      { headers: { Accept: 'application/json', ...authHeaders(settings.apiKey) }, cache: 'no-store' }
    );
    if (res.status === 404) return NextResponse.json({ error: 'Conversation not found.' }, { status: 404 });
    if (!res.ok) {
      console.error(`[ai-chat] Loading conversation failed (${res.status}):`, (await res.text().catch(() => '')).slice(0, 500));
      return NextResponse.json({ error: "Couldn't load this conversation." }, { status: 502 });
    }
    return NextResponse.json({ messages: toUIMessages(await res.json()) });
  } catch (error) {
    console.error('[ai-chat] Loading conversation failed:', error);
    return NextResponse.json({ error: "Couldn't load this conversation." }, { status: 502 });
  }
}
